Worked CPU reference: read it after drafting your own shape and mask plan. This uses finite differences for the short training demonstration; it does not implement reverse-mode training or establish independent code authorship. All dependencies are in the Python standard library.

```python
import math

def dot(a,b):
    return sum(x*y for x,y in zip(a,b))
def mm(a,b):
    return [[dot(row,col) for col in zip(*b)] for row in a]
def add(a,b):
    return [[x+y for x,y in zip(r,s)] for r,s in zip(a,b)]
def rms(rows):
    return [[x/math.sqrt(dot(row,row)/len(row)+1e-5)
             for x in row] for row in rows]
def softmax(row):
    m=max(row)
    e=[math.exp(x-m) for x in row]
    return [x/sum(e) for x in e]

def decoder(theta,ids,causal=True):
    it=iter(theta)
    def matrix(n,m):
        return [[next(it) for _ in range(m)] for _ in range(n)]
    E,P=matrix(3,2),matrix(2,2)
    Wq,Wk,Wv,Wo=[matrix(2,2) for _ in range(4)]
    Wu,Wd,Wh=matrix(2,3),matrix(3,2),matrix(2,3)
    x=add([E[t] for t in ids],P[:len(ids)])
    norm=rms(x)
    q,k,v=[mm(norm,w) for w in [Wq,Wk,Wv]]
    mixed=[]
    for i,query in enumerate(q):
        allowed=list(range(i+1 if causal else len(ids)))
        scores=[dot(query,k[j])/math.sqrt(2) for j in allowed]
        prob=softmax(scores)
        mixed.append([sum(a*v[j][d] for a,j in zip(prob,allowed))
                      for d in range(2)])
    r=add(x,mm(mixed,Wo))
    hidden=[[math.tanh(z) for z in row] for row in mm(rms(r),Wu)]
    return mm(add(r,mm(hidden,Wd)),Wh)

windows=[([0,1],[1,2]),([1,2],[2,0]),([2,0],[0,1])]
def objective(theta):
    total=0.0
    for ids,targets in windows:
        for row,target in zip(decoder(theta,ids),targets):
            m=max(row)
            total+=m+math.log(sum(math.exp(z-m) for z in row))-row[target]
    return total/6

def numerical_gradient(theta,h=1e-5):
    result=[]
    for i in range(len(theta)):
        plus,minus=theta[:],theta[:]
        plus[i]+=h
        minus[i]-=h
        result.append((objective(plus)-objective(minus))/(2*h))
    return result

theta=[0.2*math.sin(i+1) for i in range(44)]
initial=objective(theta)
for _ in range(12):
    gradient=numerical_gradient(theta)
    theta=[w-0.1*g for w,g in zip(theta,gradient)]
final=objective(theta)
assert final < initial
```
